#!/usr/bin/env bash
set -euo pipefail

# Golden Steam Gamescope - Trainer launcher
# Generated by CrossHook
# https://github.com/yandy-r/crosshook
# Launch this after the game has reached the in-game menu.
# Trainer loading mode: source_directory
# Network isolation: disabled
PREFIX_ROOT='/fake/prefix'
if [[ "${PREFIX_ROOT##*/}" == "pfx" ]]; then
  export WINEPREFIX="$PREFIX_ROOT"
  export STEAM_COMPAT_DATA_PATH="$(dirname "$PREFIX_ROOT")"
elif [[ -d "$PREFIX_ROOT/pfx" ]]; then
  export WINEPREFIX="$PREFIX_ROOT/pfx"
  export STEAM_COMPAT_DATA_PATH="$PREFIX_ROOT"
else
  export WINEPREFIX="$PREFIX_ROOT"
  export STEAM_COMPAT_DATA_PATH="$PREFIX_ROOT"
fi
export STEAM_COMPAT_CLIENT_INSTALL_PATH='/fake/steam'
PROTON='/fake/proton/proton'
TRAINER_HOST_PATH='@HOME@/trainers/Stub Trainer.exe'

# Gamescope wrapper — launches trainer in its own compositor session.
_GAMESCOPE_ARGS=('-w' '1280' '-h' '720' '-W' '1920' '-H' '1080' '-r' '60' '-f')
if [[ -z "${GAMESCOPE_WAYLAND_DISPLAY:-}" ]]; then
  _GS_PREFIX=(gamescope "${_GAMESCOPE_ARGS[@]}" --)
else
  _GS_PREFIX=()
fi


trainer_host_path="$(realpath "$TRAINER_HOST_PATH")"
trainer_host_dir="$(dirname "$trainer_host_path")"
cd "$trainer_host_dir"

_UMU_AVAILABLE=0
if command -v umu-run >/dev/null 2>&1; then
  _UMU_AVAILABLE=1
fi
if [ "$_UMU_AVAILABLE" = "1" ]; then
  # External launcher exports use profile and Steam GAMEID fields only; online lookup is resolved during CrossHook launch and preview commands.
  export GAMEID='12345'
  export PROTON_VERB='runinprefix'
  export PROTONPATH='/fake/proton'
  exec "${_GS_PREFIX[@]}" umu-run "$trainer_host_path"
else
  unset GAMEID PROTON_VERB PROTONPATH
exec "${_GS_PREFIX[@]}" "$PROTON" run "$trainer_host_path"
fi
